  );

  /// Upsert many documents in a single FFI call. Does not commit.
  Future<void> upsertDocumentsBatch({required List<DocumentInput> docs}) =>
      RustLib.instance.api.crateApiSearchEngineSearchEngineUpsertDocumentsBatch(
        that: this,
